<?php declare(strict_types=1); namespace App\People\Infrastructure\Persistence\DBAL; use App\People\Domain\Model\Family; use App\People\Domain\Repository\FamilyRepository; use App\People\Domain\ValueObject\FamilyId; use Doctrine\DBAL\Connection; final readonly class DbalFamilyRepository implements FamilyRepository {public function __construct(private Connection $connection,private FamilyMapper $mapper){} public function save(Family $f):void{$this->connection->beginTransaction();try{$d=$this->mapper->toRow($f);$exists=$this->connection->fetchOne('SELECT 1 FROM people_families WHERE id=:id',['id'=>$f->id()->toString()]);if($exists){unset($d['id']);$this->connection->update('people_families',$d,['id'=>$f->id()->toString()]);}else{$this->connection->insert('people_families',$d);}$this->connection->delete('people_family_memberships',['family_id'=>$f->id()->toString()]);foreach($f->members() as $m)$this->connection->insert('people_family_memberships',['id'=>\Symfony\Component\Uid\Uuid::v7()->toRfc4122(),'family_id'=>$f->id()->toString(),'person_id'=>$m->personId()->toString(),'role'=>$m->role()->value,'created_at'=>$m->createdAt()->format('Y-m-d H:i:s')]);$this->connection->commit();}catch(\Throwable $e){$this->connection->rollBack();throw $e;}} public function findById(FamilyId $id):?Family{$r=$this->connection->fetchAssociative('SELECT * FROM people_families WHERE id=:id',['id'=>$id->toString()]);if($r===false)return null;$members=$this->connection->fetchAllAssociative('SELECT person_id,role,created_at FROM people_family_memberships WHERE family_id=:id ORDER BY created_at',['id'=>$id->toString()]);return $this->mapper->toDomain($r,$members);} public function findAll():array{$rows=$this->connection->fetchAllAssociative('SELECT * FROM people_families ORDER BY name');return array_map(fn(array $r):Family=>$this->mapper->toDomain($r,$this->connection->fetchAllAssociative('SELECT person_id,role,created_at FROM people_family_memberships WHERE family_id=:id ORDER BY created_at',['id'=>$r['id']])), $rows);}}
